create table xxcus.xxfnd_attachment_blocks (
    function_code         varchar2(60 byte) not null enable,
    block_code            varchar2(60 byte) not null enable,
    region_static_id      varchar2(255 byte) not null enable,
    block_name            varchar2(240 byte),
    display_sequence      number,
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxfnd_attachment_blocks
    add constraint xxfnd_att_blocks_pk primary key ( function_code,
                                                     block_code )
        using index enable;

alter table xxcus.xxfnd_attachment_blocks
    add constraint xxfnd_att_blocks_uk1 unique ( function_code,
                                                 region_static_id )
        using index enable;


